 * Splits a string on unescaped commas.
 * Backslash may escape only comma or backslash.
 * Preserves empty fields.
 * Returns null on failure (e.g., trailing backslash or invalid escape).
 *
 * @param {string} x - Input string
 * @returns {string[]} Array of fields or null on failure
 */
exports.splitEscaped = function(x) {
  if (typeof x !== 'string') {
    return null;
  }

  const result = [];
  let i = 0;
  const len = x.length;

  while (i < len) {
    const c = x[i];

    if (c === '\\') {
      // Escaped character
      i++;
      if (i >= len) {
        // Trailing backslash
        return null;
      }
      const next = x[i];

      if (next === ',') {
        // Escaped comma
        i++;
        result.push('');
      } else if (next === '\\') {
        // Escaped backslash
        i++;
        result.push('');
      } else {
        // Invalid escape sequence
        return null;
      }
    } else {
      // Regular character
      result.push(x[i]);
      i++;
    }
  }

  return result;
};

